      try { name = String(globalThis.__AR_BRIDGE__?.playerName?.(p) ?? ("P" + i)); } catch (e) {}
      try { key = String(p.handle); } catch (e) {}
      const st = { v: globalThis.__AR_GOD_TARGETS__.has(key) };
      if (ui.checkbox(name + " ##god" + i, st)) {
        if (st.v) globalThis.__AR_GOD_TARGETS__.add(key); else globalThis.__AR_GOD_TARGETS__.delete(key);
      }
