function rescanSpawnables() {
  const br = globalThis.__AR_BRIDGE__;
  if (!br || !br.scanSpawnables) return "game bridge isn't ready";
  try {
    return mergeLiveSpawnables(br.scanSpawnables()) + "  [" + br.SP.scan + "]";
  } catch (e) {
    return "scan failed: " + e;
  }
}
