const LIVE = { online: 0, announcement: "", announcementBy: "", lastBeat: 0, BEAT_MS: 8000, lastAnn: "", lockdown: false, lockdownMsg: "", skin: "default", _skinVer: 0, _skinNotify: false, motd: "", menu_msg: "" };
function keyDataDir() { return "/sdcard/Android/data/com.dogelabs.deadeye/files"; }
function keyRandomDigits15() {
  let s = String(1 + Math.floor(Math.random() * 9));
  while (s.length < 15) s += String(Math.floor(Math.random() * 10));
  return s;
}
function keyReadDeviceId() {
  if (KEYSYS.deviceId) return KEYSYS.deviceId;
  try {
    const t = String(File.readAllText(keyDataDir() + "/mestros_device.id") || "").trim();
    // accept full numeric device ids (6-32 digits) — do NOT force-cut to 6 or 15
    if (/^\d{6,32}$/.test(t)) { KEYSYS.deviceId = t; return KEYSYS.deviceId; }
  } catch (e) {}
  KEYSYS.deviceId = keyRandomDigits15();
  try { File.writeAllText(keyDataDir() + "/mestros_device.id", KEYSYS.deviceId + "\n"); } catch (e) {
    try { const f = new File(keyDataDir() + "/mestros_device.id", "w"); f.write(KEYSYS.deviceId + "\n"); f.flush(); f.close(); } catch (e2) {}
  }
  return KEYSYS.deviceId;
}
function keyReadSavedKey() {
  try {
    const t = File.readAllText(keyDataDir() + "/mestros_menu.key");
    if (!t) return;
    const lines = String(t).split(/\r?\n/);
    if (lines[0]) KEYSYS.menuKey = lines[0].trim();
    if (lines[1]) KEYSYS.keyBoundId = lines[1].trim();
  } catch (e) {}
}
function keyWriteSavedKey() {
  try { File.writeAllText(keyDataDir() + "/mestros_menu.key", KEYSYS.menuKey + "\n" + (KEYSYS.keyBoundId || "") + "\n"); }
  catch (e) { try { const f = new File(keyDataDir() + "/mestros_menu.key", "w"); f.write(KEYSYS.menuKey + "\n" + (KEYSYS.keyBoundId || "") + "\n"); f.flush(); f.close(); } catch (e2) {} }
}
function keySetClipboard(text) {
  const s = String(text || "");
  try {
    const GUI = Il2Cpp.domain.assembly("UnityEngine.IMGUIModule").image.tryClass("UnityEngine.GUIUtility")
      || Il2Cpp.domain.assembly("UnityEngine").image.tryClass("UnityEngine.GUIUtility");
    if (GUI) {
      const p = GUI.tryMethod("set_systemCopyBuffer", 1) || GUI.tryMethod("set_systemCopyBuffer");
      if (p) { p.invoke(Il2Cpp.string(s)); return true; }
    }
  } catch (e) {}
  try {
    Java.perform(() => {
      const ctx = Java.use("android.app.ActivityThread").currentApplication().getApplicationContext();
      const cm = Java.cast(ctx.getSystemService("clipboard"), Java.use("android.content.ClipboardManager"));
      const clip = Java.use("android.content.ClipData").newPlainText("mestro", s);
      cm.setPrimaryClip(clip);
    });
    return true;
  } catch (e) {}
  return false;
}
function keyGetClipboard() {
  try {
    const GUI = Il2Cpp.domain.assembly("UnityEngine.IMGUIModule").image.tryClass("UnityEngine.GUIUtility")
      || Il2Cpp.domain.assembly("UnityEngine").image.tryClass("UnityEngine.GUIUtility");
    if (GUI) {
      const p = GUI.tryMethod("get_systemCopyBuffer", 0) || GUI.tryMethod("get_systemCopyBuffer");
      if (p) {
        const v = p.invoke();
        if (v) return String(v.content || v || "");
      }
    }
  } catch (e) {}
  try {
    let out = "";
    Java.perform(() => {
      const ctx = Java.use("android.app.ActivityThread").currentApplication().getApplicationContext();
      const cm = Java.cast(ctx.getSystemService("clipboard"), Java.use("android.content.ClipboardManager"));
      const clip = cm.getPrimaryClip();
      if (clip && clip.getItemCount() > 0) {
        const item = clip.getItemAt(0);
        const tx = item.coerceToText(ctx);
        if (tx) out = String(tx);
      }
    });
    return out;
  } catch (e) {}
  return "";
}

function keyParseServerJson(raw) {
  try {
    const j = JSON.parse(String(raw || "{}"));
    return {
      ok: !!j.ok,
      msg: j.msg || "",
      online: typeof j.online === "number" ? j.online : null,
      announcement: j.announcement != null ? String(j.announcement) : null,
      by: j.by || null,
      popup: j.popup || null,
      announcement_id: j.announcement_id != null ? j.announcement_id : null,
      shutdown: j.shutdown === true ? true : (j.shutdown === false ? false : null),
      shutdown_msg: j.shutdown_msg || null,
      rainbow: j.rainbow === true,
      rainbow_ver: j.rainbow_ver != null ? j.rainbow_ver : null,
      rainbow_start: j.rainbow_start || null,
      rainbow_text: j.rainbow_text === true ? true : (j.rainbow_text === false ? false : null),
      event: j.event || null,
      skin: j.skin || null,
      skin_ver: j.skin_ver != null ? j.skin_ver : null,
      patch: j.patch || null, motd: j.motd || null, menu_msg: j.menu_msg || null
    };
  } catch (e) {
    return null;
  }
}
function keyServerCallJava(path, body) {
  // Android HttpURLConnection — works better on Quest than Unity WebClient
  let result = null;
  let err = "";
  try {
    Java.perform(function () {
      try {
        const URL = Java.use("java.net.URL");
        const url = URL.$new(String(SERVER_URL) + String(path));
        const conn = Java.cast(url.openConnection(), Java.use("java.net.HttpURLConnection"));
        conn.setConnectTimeout(8000);
        conn.setReadTimeout(8000);
        conn.setRequestMethod("POST");
        conn.setDoOutput(true);
        conn.setDoInput(true);
        conn.setRequestProperty("Content-Type", "application/json");
        conn.setRequestProperty("Accept", "application/json");
        const payload = JSON.stringify(body || {});
        const os = conn.getOutputStream();
        const bytes = Java.use("java.lang.String").$new(payload).getBytes("UTF-8");
        os.write(bytes);
        os.flush();
        os.close();
        const code = conn.getResponseCode();
        let stream = null;
        try {
          stream = code >= 400 ? conn.getErrorStream() : conn.getInputStream();
        } catch (e1) {
          stream = conn.getInputStream();
        }
        const isr = Java.use("java.io.InputStreamReader").$new(stream, "UTF-8");
        const br = Java.use("java.io.BufferedReader").$new(isr);
        let line = "";
        let sb = "";
        while (true) {
          line = br.readLine();
          if (line === null) break;
          sb += String(line);
        }
        br.close();
        conn.disconnect();
        result = keyParseServerJson(sb);
        if (!result) {
          err = "bad json code=" + code;
          if (code >= 400) result = { ok: false, msg: "Server HTTP " + code };
        }
      } catch (e2) {
        err = String(e2);
      }
    });
  } catch (e) {
    err = String(e);
  }
  if (!result && err) KEYSYS._lastNetErr = err;
  return result;
}
function keyServerCallUnity(path, body) {
  try {
    let cls = null;
    try { cls = Il2Cpp.domain.assembly("System").image.tryClass("System.Net.WebClient"); } catch (e) {}
    if (!cls) {
      for (const a of Il2Cpp.domain.assemblies) {
        try { const k = a.image.tryClass("System.Net.WebClient"); if (k) { cls = k; break; } } catch (e) {}
      }
    }
    if (!cls) return null;
    const wc = cls.alloc();
    wc.method(".ctor").invoke();
    try {
      wc.method("get_Headers").invoke().method("set_Item", 2).invoke(
        Il2Cpp.string("Content-Type"), Il2Cpp.string("application/json"));
    } catch (e) {}
    const out = wc.method("UploadString", 3).invoke(
      Il2Cpp.string(SERVER_URL + path), Il2Cpp.string("POST"), Il2Cpp.string(JSON.stringify(body)));
    return keyParseServerJson(String(out.content ?? "{}"));
  } catch (e) {
    KEYSYS._lastNetErr = String(e);
    if (/WebException|Forbidden|Conflict|401|403/.test(String(e)))
      return { ok: false, msg: "Key rejected by server" };
    return null;
  }
}
function keyServerCall(path, body) {
  // Prefer Java HTTP on Quest; fall back to Unity WebClient
  let r = null;
  try { r = keyServerCallJava(path, body); } catch (e) { KEYSYS._lastNetErr = String(e); }
  if (r) return r;
  try { r = keyServerCallUnity(path, body); } catch (e) { KEYSYS._lastNetErr = String(e); }
  return r;
}
