function liveApply(r) {
  if (!r) return;
  if (r.rainbow_ver != null) {
    if (LIVE._rainbowVer === undefined) {
      // first reply after the menu opens: no countdown, just match the current state
      LIVE.rainbowLocalStart = Date.now() - 6000;
    } else if (Number(r.rainbow_ver) !== Number(LIVE._rainbowVer)) {
      LIVE.rainbowLocalStart = Date.now();
    }
    LIVE._rainbowVer = Number(r.rainbow_ver);
    LIVE.rainbowOn = !!r.rainbow;
    if (!LIVE.rainbowOn && LIVE._rainbowApplied && globalThis.__AR_APPLY_THEME__) {
      globalThis.__AR_APPLY_THEME__(SKIN_THEME[LIVE.skin] || THEME);
      LIVE._rainbowApplied = false;
    }
  }
  if (typeof r.online === "number") LIVE.online = r.online;
  if (r.skin_ver != null && LIVE._skinVer != null && Number(r.skin_ver) !== Number(LIVE._skinVer)) {
    LIVE._skinNotify = true;
  }
  if (r.skin_ver != null) LIVE._skinVer = r.skin_ver;
  if (r.skin) LIVE.skin = String(r.skin);
  if (r.motd != null) LIVE.motd = String(r.motd);
  if (r.menu_msg != null) LIVE.menu_msg = String(r.menu_msg);
  if (r.skin && LIVE._appliedSkin !== LIVE.skin && globalThis.__AR_APPLY_THEME__) {
    LIVE._appliedSkin = LIVE.skin;
    const mapped = SKIN_THEME[LIVE.skin];
    if (mapped) globalThis.__AR_APPLY_THEME__(mapped);
  }

  if (r.ok === false && r.msg) {
    const msg = String(r.msg);
    if (/shutdown|lockdown|mod is shut|shut down|banned|kicked|expired|revoked/i.test(msg)) {
      LIVE.lockdown = /shutdown|lockdown|mod is shut|shut down/i.test(msg);
      LIVE.lockdownMsg = msg;
      KEYSYS.menuUnlocked = false;
      KEYSYS.phase = 2;
      KEYSYS.keyMsg = msg;
      KEYSYS.keyMsgBad = true;
    }
  } else if (r.ok === true) {
    LIVE.lockdown = false; LIVE.lockdownMsg = "";
  }
  if (r.announcement != null && String(r.announcement).length) {
    LIVE.announcement = String(r.announcement); LIVE.announcementBy = r.by || "Owner";
  } else if (r.announcement === "") { LIVE.announcement = ""; LIVE.announcementBy = ""; }
}
function keyCheckServer() {
  if (!KEYSYS.menuKey) return;
  const r = keyServerCall("/validate", { key: KEYSYS.menuKey, device_id: keyReadDeviceId(), target: "ar", version: MENU_VERSION });
  KEYSYS.lastValidateAt = Date.now();
  if (!r) { if (!KEYSYS.menuUnlocked) { KEYSYS.keyMsg = "Server unreachable — bot offline or bad SERVER_URL"; KEYSYS.keyMsgBad = true; } return; }
  liveApply(r);
  if (r.ok) { KEYSYS.menuUnlocked = true; KEYSYS.phase = 3; KEYSYS.keyMsg = "Unlocked"; KEYSYS.keyMsgBad = false; return; }
  KEYSYS.menuUnlocked = false; KEYSYS.phase = 2; KEYSYS.keyMsg = r.msg || "Link device in Discord"; KEYSYS.keyMsgBad = true;
}
function keyTryActivate() {
  const typed = String(KEYSYS.keyEntry.v || "").trim();
  if (!typed) { KEYSYS.keyMsg = "Type key from Discord"; KEYSYS.keyMsgBad = true; return; }
  const r = keyServerCall("/activate", { key: typed, device_id: keyReadDeviceId(), target: "ar", version: MENU_VERSION });
  if (!r) { KEYSYS.keyMsg = "Server unreachable — check bot is online + SERVER_URL. " + (KEYSYS._lastNetErr || "").slice(0, 80); KEYSYS.keyMsgBad = true; return; }
  if (!r.ok) { KEYSYS.keyMsg = r.msg || "Key rejected"; KEYSYS.keyMsgBad = true; return; }
  KEYSYS.menuKey = typed; keyWriteSavedKey(); KEYSYS.phase = 2;
  KEYSYS.keyMsg = "Key saved. Link device " + keyReadDeviceId() + " in Discord, then press Linked Device"; KEYSYS.keyMsgBad = false;
}

// Second layer: the player presses "Linked Device" and the bot checks the key + device link.
function keyLinkedCheck() {
  if (!KEYSYS.menuKey) { KEYSYS.keyMsg = "Enter and activate your key first"; KEYSYS.keyMsgBad = true; return; }
  const r = keyServerCall("/validate", { key: KEYSYS.menuKey, device_id: keyReadDeviceId(), target: "ar", version: MENU_VERSION });
  KEYSYS.lastValidateAt = Date.now();
  if (!r) { KEYSYS.keyMsg = "Server unreachable - check bot is online and SERVER_URL"; KEYSYS.keyMsgBad = true; return; }
  if (r.ok) {
    KEYSYS.menuUnlocked = true; KEYSYS.phase = 3;
    KEYSYS.keyMsg = "Thanks for linking! Everything is working. Enjoy the mods."; KEYSYS.keyMsgBad = false;
    return;
  }
  KEYSYS.menuUnlocked = false; KEYSYS.phase = 2;
  KEYSYS.keyMsg = "Sorry, you didn't link. Please link in the Discord, then press Linked Device."; KEYSYS.keyMsgBad = true;
}
function playLoadSoundOnce() {
  if (KEYSYS._loadSound) return; KEYSYS._loadSound = true;
  try {
    Java.perform(function () {
      try {
        const MediaPlayer = Java.use("android.media.MediaPlayer");
        const mp = MediaPlayer.$new();
        for (const path of ["/sdcard/Download/mestros_load.mp3", keyDataDir() + "/mestros_load.mp3"]) {
          try { mp.setDataSource(path); mp.prepare(); mp.start(); return; } catch (e) {}
        }
      } catch (e) {}
    });
  } catch (e) {}
}
function keyBootOnce() {
  if (KEYSYS._booted) return; KEYSYS._booted = true;
  KEYSYS.menuUnlocked = true; KEYSYS.phase = 3; // key system removed
  keyReadSavedKey(); keyReadDeviceId(); playLoadSoundOnce();
  if (KEYSYS.menuKey) { KEYSYS.phase = 2; keyCheckServer(); }
}
function liveHeartbeat() {
  if (!KEYSYS.menuUnlocked) return;
  if (Date.now() - LIVE.lastBeat < LIVE.BEAT_MS) return;
  LIVE.lastBeat = Date.now();
  const r = keyServerCall("/heartbeat", { key: KEYSYS.menuKey, device_id: keyReadDeviceId(), menu: MENU_TITLE, target: "ar", version: MENU_VERSION });
  if (r) { liveApply(r); liveApplyExtras(r); }
}
function drawKeyGate(ui) {
  return false; // key system removed
  keyBootOnce();
  const accent = [0.78, 0.66, 1, 1], bad = [1, 0.45, 0.45, 1], good = [0.35, 0.95, 0.45, 1];
  if (KEYSYS.phase === 0) {
    const tt = Date.now() - KEYSYS.loadStart, p = Math.min(1, tt / KEYSYS.LOAD_MS);
    ui.spacing(); ui.textColored(accent, MENU_TITLE); ui.separator();
    ui.text("Loading..."); if (ui.progressBar) ui.progressBar(p);
    ui.textDisabled(Math.floor(p * 100) + "%");
    ui.textDisabled("thanks for useing mestros mod menu it means a lot.");
    if (tt >= KEYSYS.LOAD_MS) { KEYSYS.phase = KEYSYS.menuKey ? 2 : 1; if (KEYSYS.menuKey) keyCheckServer(); }
    return true;
  }
  if (KEYSYS.menuUnlocked || KEYSYS.phase === 3) {
    KEYSYS.phase = 3; KEYSYS.menuUnlocked = true;
    if (Date.now() - KEYSYS.lastValidateAt > 60000 && KEYSYS.menuKey) keyCheckServer();
    return false;
  }
  const dev = keyReadDeviceId();
  if (KEYSYS.phase === 1) {
    ui.spacing(); ui.textColored(accent, "Welcome to " + MENU_TITLE); ui.separator();
    ui.text("1) Get your key from Discord /panel (Generate Key or Trail)");
    ui.text("2) Paste key here  3) Copy Device ID  4) Link in Discord  5) Linked Device");
    if (DISCORD_URL && ui.button("Open Discord")) ui.openUrl(DISCORD_URL);
  if (ui.button("Buy Supporter (Discord)")) ui.openUrl("https://discord.gg/yCYvfDaa8");
  if (ui.button("Buy Roblox Shirt")) ui.openUrl("https://www.roblox.com/catalog/1747099826");
    ui.spacing();
    ui.text("Your Device ID:");
    ui.textColored(accent, dev);
    if (ui.button("Copy Device ID")) {
      if (keySetClipboard(dev)) { KEYSYS.keyMsg = "Device ID copied"; KEYSYS.keyMsgBad = false; }
      else { KEYSYS.keyMsg = "Copy failed - write it down: " + dev; KEYSYS.keyMsgBad = true; }
    }
    ui.spacing();
    ui.inputText("Key", KEYSYS.keyEntry);
    if (ui.button("Paste Key from Clipboard")) {
      const clip = String(keyGetClipboard() || "").trim();
      if (clip) { KEYSYS.keyEntry.v = clip; KEYSYS.keyMsg = "Key pasted"; KEYSYS.keyMsgBad = false; }
      else { KEYSYS.keyMsg = "Clipboard empty - copy key from Discord first"; KEYSYS.keyMsgBad = true; }
    }
    if (ui.button("Continue / Activate Key")) keyTryActivate();
    if (KEYSYS.keyMsg) { ui.spacing(); ui.textColored(KEYSYS.keyMsgBad ? bad : good, KEYSYS.keyMsg); }
    return true;
  }
  ui.spacing(); ui.textColored(accent, "Link Device"); ui.separator();
  ui.text("Open Discord /panel -> Link Device, paste key + this Device ID.");
  ui.textColored(accent, dev);
  if (ui.button("Copy Device ID")) {
    if (keySetClipboard(dev)) { KEYSYS.keyMsg = "Device ID copied - paste it in Discord Link Device"; KEYSYS.keyMsgBad = false; }
    else { KEYSYS.keyMsg = "Copy failed - use this ID: " + dev; KEYSYS.keyMsgBad = true; }
  }
  if (DISCORD_URL && ui.button("Open Discord")) ui.openUrl(DISCORD_URL);
  ui.spacing();
  if (ui.button("Linked Device")) keyLinkedCheck();
  if (ui.button("Re-enter Key")) { KEYSYS.phase = 1; KEYSYS.menuKey = ""; KEYSYS.keyEntry.v = ""; KEYSYS.keyMsg = ""; }
  if (KEYSYS.keyMsg) { ui.spacing(); ui.textColored(KEYSYS.keyMsgBad ? bad : good, KEYSYS.keyMsg); }
  return true;
}


