const SHUT_TEXT = "This mod menu has been shut down please use the new one or check announcements";
LIVE.annId = -1;
LIVE.popup = null;
LIVE.popupSkipped = 0;
LIVE.shut = false;
function liveApplyExtras(r) {
  if (!r) return;
  if (r.rainbow_text === true || r.rainbow_text === false) LIVE.rbText = r.rainbow_text;
  if (r.event) LIVE.ev = r.event; else if (r.event === null) LIVE.ev = null;
  LIVE.ev = (r.event && r.event.type) ? r.event : null;
  if (r.event && r.event.type === "matrix") {
    if (!LIVE.mx || LIVE.mx.id !== r.event.id) {
      LIVE.mx = { id: r.event.id, phase: "count", start: Date.now(),
        count: Math.max(1, Math.min(30, parseInt(r.event.text, 10) || 5)),
        endMs: r.event.ends_at ? r.event.ends_at * 1000 : 0 };
    }
  } else if (r.event === null && LIVE.mx) {
    LIVE.mx = null;
  }
  if (typeof r.announcement_id === "number") {
    const first = LIVE.annId === -1;
    LIVE.annId = r.announcement_id;
    if (!first && r.announcement && String(r.announcement).length) {
      try { if (globalThis.ui && ui.notify) ui.notify("ANNOUNCEMENT: " + String(r.announcement), 12); } catch (e) { }
    }
  }
  if (r.shutdown === true) LIVE.shut = true;
  else if (r.shutdown === false) LIVE.shut = false;
  if (r.popup && r.popup.id) {
    if (!LIVE.popup || LIVE.popup.id !== r.popup.id) LIVE.popup = r.popup;
  } else if (r.popup === null) {
    LIVE.popup = null;
  }
}
