  if (S4.hudApp.v) hud.line(hud.app);
  if (S4.hudFps.v) hud.line("FPS: " + hud.col(hud.fps.toFixed(0), hud.fps >= 65 ? hud.GOOD : hud.fps >= 45 ? hud.WARN : hud.BAD));
